function validate([arr]) {
  if (!Array.isArray(arr) || arr.length < 2 || arr.length > 100000) return 'arr needs 2 to 100000 values.';
  if (arr.some(v => !Number.isInteger(v) || v < -1000000 || v > 1000000)) return 'Each value is between -10^6 and 10^6.';
  if (new Set(arr).size !== arr.length) return 'The values must be distinct.';
  return null;
}

