function minimumAbsDifference(arr) {
  arr.sort((a, b) => a - b);
  let smallest = Infinity;

  for (let i = 1; i < arr.length; i++) {
    smallest = Math.min(smallest, arr[i] - arr[i - 1]);
  }

  const pairs = [];
  for (let i = 1; i < arr.length; i++) {
    if (arr[i] - arr[i - 1] === smallest) {
      pairs.push([arr[i - 1], arr[i]]);
    }
  }
  return pairs;
}

