function minimumAbsDifference(arr) {
  let least = Infinity;
  for (let i = 0; i < arr.length; i++)
    for (let j = i + 1; j < arr.length; j++) least = Math.min(least, Math.abs(arr[i] - arr[j]));
  const found = [];
  for (let i = 0; i < arr.length; i++)
    for (let j = 0; j < arr.length; j++)
      if (arr[j] - arr[i] === least) found.push([arr[i], arr[j]]);
  return found.sort((p, q) => p[0] - q[0] || p[1] - q[1]);
}

