function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 2 + Math.floor(rand() * 7);
  // Some inputs use only multiples of step, so several pairs tie for the smallest gap.
  const step = size === 'large' ? (rand() < 0.5 ? 1 : 500) : (rand() < 0.5 ? 1 : 3);
  const slots = size === 'large' ? Math.floor(1000000 / step) : n + Math.floor(rand() * 10);
  const values = new Set();
  while (values.size < n) values.add((Math.floor(rand() * (2 * slots + 1)) - slots) * step);
  return [[...values]];
}
